        dark[n - 1] = 1

    first_zero = -1
    for i in range(n):
        if dark[i] == 0:
            first_zero = i
            break

    if first_zero == -1:
        print(n)
        return

    max_streak = 0
    current_streak = 0
    for i in range(n):
        idx = (first_zero + 1 + i) % n
        if dark[idx] == 1:
            current_streak += 1
            if current_streak > max_streak:
                max_streak = current_streak
        else:
            current_streak = 0

    print(max_streak)

